// Same-product helpers.
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const words = t => String(t || '').toLowerCase().match(/[a-z0-9]+/g) || [];
// The model as a whole token: C410 matches "Tapo C410" and "C410(2-Pack)" but not "C4100".
const hasModel = (text, model) => {
  const parts = String(model || '').match(/[a-z0-9]+/gi);
  if (!parts) return false;
  return new RegExp('(^|[^a-z0-9])' + parts.map(esc).join('[\\s_-]*') + '($|[^a-z0-9])', 'i').test(String(text || ''));
};
// Words that make a page a different product from a single item: kit, 2-pack, bundle...
const packWords = (t, list) => words(t).filter(w => list.includes(w) || /^\d+pack$/.test(w));
const extraPack = (theirs, ours, list) => [...new Set(packWords(theirs, list).filter(w => !packWords(ours, list).includes(w)))];
// Without a model number, the titles must match word for word once the brand is taken out.
const sameName = (a, b, brand) => {
  const skip = new Set(words(brand));
  const clean = t => words(t).filter(w => !skip.has(w)).join(' ');
  return clean(a) !== '' && clean(a) === clean(b);
};

// For each product: the page you pasted, or a search of each manufacturer site's own store search.
// Why Code: one search per site per product with a pause between them, then a pick from the results.
const s = $('Find settings').first().json;
const d = $('Get products').first().json.data || {};
const products = (d.products?.nodes || d.nodes || []).filter(p => p && p.id);
const sites = $('Get sites').all().map(i => i.json).filter(x => x.domain);
// A product that already has a page (other than "not found") is done: Find only untags it.
const done = new Set($('Get sources').all().map(i => i.json).filter(r => r.product_id && r.status !== 'not_found').map(r => r.product_id));
const sleep = ms => new Promise(r => setTimeout(r, ms));
const out = [];
for (const p of products) {
  const base = { product_id: p.id, product_title: p.title, product_handle: p.handle, brand: p.vendor || '', model: String(p.model?.value || '').trim() };
  if (done.has(p.id)) { out.push({ json: { ...base, skip: true } }); continue; }
  const pasted = String(p.page?.value || '').trim();
  const mine = sites.filter(x => String(x.brand).toLowerCase() === base.brand.toLowerCase());
  if (pasted) {
    const site = mine.find(x => pasted.includes(x.domain)) || {};
    out.push({ json: { ...base, url: pasted, source_name: site.source_name || base.brand, found_by: 'pasted', status: 'new', note: '' } });
    continue;
  }
  if (!mine.length) { out.push({ json: { ...base, url: '', source_name: '', found_by: 'search', status: 'not_found', note: 'No manufacturer site for ' + (base.brand || 'this vendor') + ' in review_sites' } }); continue; }
  let pick = null, notes = [];
  for (const site of mine) {
    // A Shopify store's own search: free, and it returns the product titles to check.
    const q = base.model || base.product_title.replace(new RegExp(esc(base.brand), 'ig'), '').trim();
    let hits = [];
    try {
      const r = await this.helpers.httpRequest({ url: 'https://' + site.domain + '/search/suggest.json', json: true, timeout: 20000,
        qs: { q, 'resources[type]': 'product', 'resources[limit]': 10 }, headers: { 'User-Agent': s.user_agent } });
      hits = r?.resources?.results?.products || [];
    } catch (e) { notes.push(site.domain + ': ' + String(e.message).slice(0, 80)); }
    for (const h of hits) {
      const ok = base.model ? hasModel(h.title, base.model) : sameName(h.title, base.product_title, base.brand);
      const extra = extraPack(h.title, base.product_title, s.pack_words);
      if (!ok) continue;
      if (extra.length) { notes.push('Skipped ' + h.title + ' (' + extra.join(', ') + ')'); continue; }
      pick ||= { url: 'https://' + site.domain + String(h.url).split('?')[0], source_name: site.source_name, page_title: h.title };
    }
    if (pick) break;
    await sleep(1000);
  }
  out.push({ json: { ...base, url: pick?.url || '', source_name: pick?.source_name || '', found_by: 'search',
    status: pick ? 'new' : 'not_found', note: (pick ? 'Found ' + pick.page_title + '. ' : 'No matching product. ') + notes.join('; ') } });
}
return out;

// New pages first, then failed ones worth another try, then approved pages due a weekly re-read.
const s = $('Collect settings').first().json;
const now = Date.now(), H = 3600e3, D = 24 * H;
const age = r => now - new Date(r.checked_at || r.updatedAt || 0).getTime();
const due = $input.all().map(i => i.json).filter(r => r.url && (
  r.status === 'new' ||
  (r.status === 'failed' && (r.attempts || 0) < s.max_attempts && age(r) > s.retry_hours * H) ||
  (['approved', 'no_reviews'].includes(r.status) && age(r) > s.recheck_days * D)));
due.sort((a, b) => (a.status === 'new' ? 0 : 1) - (b.status === 'new' ? 0 : 1) || a.id - b.id);
return due.slice(0, s.batch_size).map(json => ({ json }));

// Same-product helpers.
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const words = t => String(t || '').toLowerCase().match(/[a-z0-9]+/g) || [];
// The model as a whole token: C410 matches "Tapo C410" and "C410(2-Pack)" but not "C4100".
const hasModel = (text, model) => {
  const parts = String(model || '').match(/[a-z0-9]+/gi);
  if (!parts) return false;
  return new RegExp('(^|[^a-z0-9])' + parts.map(esc).join('[\\s_-]*') + '($|[^a-z0-9])', 'i').test(String(text || ''));
};
// Words that make a page a different product from a single item: kit, 2-pack, bundle...
const packWords = (t, list) => words(t).filter(w => list.includes(w) || /^\d+pack$/.test(w));
const extraPack = (theirs, ours, list) => [...new Set(packWords(theirs, list).filter(w => !packWords(ours, list).includes(w)))];
// Without a model number, the titles must match word for word once the brand is taken out.
const sameName = (a, b, brand) => {
  const skip = new Set(words(brand));
  const clean = t => words(t).filter(w => !skip.has(w)).join(' ');
  return clean(a) !== '' && clean(a) === clean(b);
};

// Reads every review of each page, checks the set, and turns each review into a review-app row.
// Why Code: Judge.me's widget pages through its reviews (a loop), and the checks compare the whole set.
const s = $('Collect settings').first().json;
const pages = $('Pick due pages').all().map(i => i.json);
const http = o => this.helpers.httpRequest({ timeout: 30000, ...o, headers: { 'User-Agent': s.user_agent, ...(o.headers || {}) } });
const sleep = ms => new Promise(r => setTimeout(r, ms));
const decode = t => String(t || '').replace(/&#(x[0-9a-f]+|\d+);/gi, (_, n) => String.fromCodePoint(n[0].toLowerCase() === 'x' ? parseInt(n.slice(1), 16) : Number(n)))
  .replace(/&quot;/g, '"').replace(/&#039;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const text = h => decode(String(h || '').replace(/<br\s*\/?>|<\/p>\s*<p[^>]*>/gi, '\n').replace(/<[^>]+>/g, '')).replace(/\n{3,}/g, '\n\n').trim();
const attr = (h, k) => (h.match(new RegExp('\\b' + k + "=[\"']([^\"']*)[\"']", 'i')) || [])[1];
const classText = (h, c) => { const m = h.match(new RegExp('<(div|b|span|p)\\b[^>]*class=["\'][^"\']*\\b' + c + '\\b[^>]*>([\\s\\S]*?)</\\1>', 'i')); return m ? text(m[2]) : ''; };
const handleOf = u => (String(u || '').match(/\/products\/([^/?#]+)/) || [])[1] || '';
const IMPORTED = 'review_collected_from_another_provider';

// Judge.me's older widget sends HTML; its newer one sends JSON. Both come from the same public endpoint.
const fromHtml = html => {
  // Each review is a div whose class list has jdgm-rev on its own (not jdgm-rev-widg__reviews).
  const starts = [...html.matchAll(/<div\b[^>]*class=['"](?:[^'"]*\s)?jdgm-rev(?:\s[^'"]*)?['"][^>]*>/gi)];
  return starts.map((m, i) => {
    const b = html.slice(m.index, starts[i + 1]?.index ?? html.length);
    return { id: attr(m[0], 'data-review-id'), rating: Number(attr(b, 'data-score')), title: classText(b, 'jdgm-rev__title'),
      body: classText(b, 'jdgm-rev__body'), author: classText(b, 'jdgm-rev__author'), date: (b.match(/<time[^>]*datetime=['"]([^'"]+)/i) || [])[1],
      product_url: attr(m[0], 'data-product-url') || '', product_title: decode(attr(m[0], 'data-product-title') || ''),
      imported: (attr(b, 'data-badge-type') || '') === IMPORTED,
      pictures: [...b.matchAll(/(?:href|data-mfp-src)=['"](https:\/\/[^'"]+\.(?:jpe?g|png|webp)[^'"]*)['"]/gi)].map(x => decode(x[1])) };
  });
};
const fromJson = x => ({ id: x.uuid, rating: Number(x.rating), title: x.title || '', body: text(x.body_html), author: x.reviewer_name, date: x.created_at,
  product_url: x.product_url || '', product_title: x.product_title || '', imported: (x.transparency_badges || []).includes(IMPORTED),
  pictures: (x.pictures_urls || []).map(p => typeof p === 'string' ? p : (p.original || p.huge || p.compact || p.url || '')) });

async function judgeMe(html, page) {
  if (!/judge\.me|jdgm/i.test(html)) return null;
  const shop = (html.match(/Shopify\.shop\s*=\s*["']([^"']+)/) || html.match(/([a-z0-9][a-z0-9-]*\.myshopify\.com)/i) || [])[1];
  if (!shop) return null;
  // The product's own JSON gives the id Judge.me files reviews under, and its handle.
  const product = await http({ url: page.url.split(/[?#]/)[0] + '.js', json: true });
  const widget = (html.match(/<div\b[^>]*class=['"][^'"]*\bjdgm-rev-widg\b[^'"]*['"][^>]*>/i) || [''])[0];
  let total = null, avg = Number(attr(widget, 'data-average-rating')) || null, reviews = [];
  for (let n = 1; n <= s.max_pages; n++) {
    const r = await http({ url: 'https://api.judge.me/reviews/reviews_for_widget', json: true,
      qs: { url: shop, shop_domain: shop, platform: 'shopify', page: n, per_page: 30, product_id: String(product.id) } });
    const batch = Array.isArray(r.reviews) ? r.reviews.map(fromJson) : fromHtml(String(r.html || ''));
    total = Number(Array.isArray(r.reviews) ? r.number_of_reviews : r.total_count);
    if (Array.isArray(r.reviews) && r.average_rating) avg = Number(r.average_rating);
    reviews.push(...batch);
    if (!batch.length || reviews.length >= total) break;
    await sleep(500);
  }
  return { reader: 'Judge.me', total, avg, reviews, handle: product.handle, page_title: product.title };
}

// Any site: a Product in the page's structured data that lists every review.
function structured(html, page) {
  const found = [];
  const walk = x => { if (Array.isArray(x)) x.forEach(walk); else if (x && typeof x === 'object') { if ([x['@type']].flat().includes('Product')) found.push(x); if (x['@graph']) walk(x['@graph']); } };
  for (const m of html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)) { try { walk(JSON.parse(m[1])); } catch (e) {} }
  const p = found.length === 1 ? found[0] : found.find(x => page.model && (hasModel(x.mpn, page.model) || hasModel(x.sku, page.model) || hasModel(x.name, page.model)));
  if (!p || !p.aggregateRating || !p.review) return null;
  const reviews = [p.review].flat().map((r, i) => ({ id: r['@id'] || r.identifier || [r.author?.name || r.author, r.datePublished, i].join('|'),
    rating: Number(r.reviewRating?.ratingValue), title: text(r.name), body: text(r.reviewBody), author: r.author?.name || r.author, date: r.datePublished,
    product_url: '', product_title: '', imported: false, pictures: [r.image || []].flat().map(x => typeof x === 'string' ? x : x?.url || '') }));
  return { reader: 'Structured data', total: Number(p.aggregateRating.reviewCount || p.aggregateRating.ratingCount), avg: Number(p.aggregateRating.ratingValue),
    reviews, handle: handleOf(page.url), page_title: text(p.name) };
}

const ddmmyyyy = d => d.toISOString().slice(0, 10).split('-').reverse().join('/');
const stars = list => [5, 4, 3, 2, 1].map(n => n + '★ ' + list.filter(x => x.rating === n).length).join(' · ');
function toRow(r, page) {
  // The review app's columns. The text, rating and date are the manufacturer's, unchanged.
  let body = r.body, cont = '';
  if (body.length > 5000) { let cut = body.lastIndexOf(' ', 5000); if (cut < 4000) cut = 5000; cont = body.slice(cut).trim(); body = body.slice(0, cut).trim(); }
  const pics = [...new Set(r.pictures.filter(u => /^https:\/\/\S+\.(?:jpe?g|png)(?:[?#]|$)/i.test(u)))];
  return { title: r.title || '', body, rating: r.rating, review_date: ddmmyyyy(new Date(r.date)), reviewer_name: String(r.author || 'Anonymous').trim().slice(0, 100),
    reviewer_email: '', product_handle: page.product_handle, picture_urls: pics.slice(0, s.max_photos).join(','), curated: 'ok', reply: '',
    'CFFirst published on': page.source_name, 'CFSource page': page.url, 'CFReview continued': cont, _photos_left_out: Math.max(0, pics.length - s.max_photos) };
}

async function read(page, res) {
  const code = Number(res.statusCode) || 0, html = typeof res.body === 'string' ? res.body : (typeof res.data === 'string' ? res.data : '');
  if (code >= 400 || !html) return { status: 'failed', error: 'The page answered ' + (code || 'nothing') };
  const title = text((html.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  // Same product: the page names the model (or has the same name), and isn't a kit or pack of it.
  if (page.model && !hasModel(title + ' ' + page.url, page.model)) return { status: 'mismatch', page_title: title, error: "The page title doesn't name " + page.model };
  const extra = extraPack(title, page.product_title, s.pack_words);
  if (extra.length) return { status: 'mismatch', page_title: title, error: 'The page is a ' + [...new Set(extra)].join(', ') + " and your product isn't" };
  const r = await judgeMe(html, page) || structured(html, page);
  if (!r) return { status: 'unsupported', page_title: title, error: 'No Judge.me widget or complete review list on the page' };
  // Complete set: every review the page says it has, no duplicates, and the same average.
  if (r.reviews.some(x => !x.id)) return { status: 'failed', reader: r.reader, error: 'A review without an id: the page layout may have changed' };
  const ids = new Set(r.reviews.map(x => String(x.id)));
  if (!Number.isFinite(r.total)) return { status: 'unsupported', reader: r.reader, error: 'The page gives no review count' };
  if (r.total === 0) return { status: 'no_reviews', reader: r.reader, page_title: r.page_title, stated_count: 0 };
  if (ids.size !== r.reviews.length) return { status: 'failed', reader: r.reader, error: 'Duplicate review ids' };
  if (r.reviews.length < r.total) return { status: 'incomplete', reader: r.reader, stated_count: r.total, error: 'Read ' + r.reviews.length + ' of ' + r.total + ' reviews' };
  const mean = r.reviews.reduce((a, x) => a + x.rating, 0) / r.reviews.length;
  if (r.avg && Math.abs(mean - r.avg) > 0.051) return { status: 'failed', reader: r.reader, error: 'Average ' + mean.toFixed(2) + " doesn't match the page's " + r.avg };
  // Then keep only what belongs on your product page.
  const left = {};
  const drop = (x, why) => { left[why] = (left[why] || 0) + 1; return false; };
  const before = t => String(t || '').split(' | ')[0].trim().toLowerCase();
  const kept = r.reviews.filter(x => {
    const h = handleOf(x.product_url);
    // page: only reviews filed under this product page. title: also its other colours, named the same before " | ".
    const samePage = !h || h === r.handle;
    const sameTitle = s.same_product === 'title' && x.product_title && before(x.product_title) === before(r.page_title);
    if (!samePage && !sameTitle) return drop(x, 'other products');
    if (s.skip_imported && x.imported) return drop(x, 'imported from another site');
    if (!(x.rating >= 1 && x.rating <= 5)) return drop(x, 'no star rating');
    if (!String(x.body || '').trim()) return drop(x, 'stars only, no text');
    if (!Number.isFinite(new Date(x.date).getTime())) return drop(x, 'no date');
    return true;
  });
  const rows = kept.map(x => ({ review_id: String(x.id), rating: x.rating, row: toRow(x, page) }));
  const photos = rows.reduce((a, x) => a + x.row._photos_left_out, 0);
  if (photos) left['photos over ' + s.max_photos + ' a review'] = photos;
  const sorted = [...kept].sort((a, b) => a.rating - b.rating);
  const brief = x => x && { rating: x.rating, title: x.title, body: x.body.slice(0, 1200), author: x.author, date: String(x.date).slice(0, 10) };
  return { status: kept.length ? 'ready' : 'no_reviews', reader: r.reader, page_title: r.page_title, stated_count: r.total, review_count: kept.length,
    average: kept.length ? Math.round(kept.reduce((a, x) => a + x.rating, 0) / kept.length * 100) / 100 : null, stars: stars(kept),
    left_out: Object.entries(left).map(([k, v]) => v + ' ' + k).join(', '), lowest: brief(sorted[0]), highest: brief(sorted[sorted.length - 1]), rows };
}

const out = [];
for (let i = 0; i < pages.length; i++) {
  const page = pages[i];
  let r;
  try { r = await read(page, $input.all()[i]?.json || {}); } catch (e) { r = { status: 'failed', error: String(e.message).slice(0, 300) }; }
  // An approved page stays approved; its new reviews flow straight to Export.
  const status = page.status === 'approved' ? 'approved' : r.status;
  out.push({ json: { ...page, ...r, status, rows: r.rows || [], error: r.error || '', attempts: r.status === 'failed' ? (page.attempts || 0) + 1 : 0 } });
}
return out;

return $input.all().flatMap(i => i.json.rows.map(r => ({ json: {
  key: i.json.id + ':' + r.review_id, source_id: i.json.id, product_id: i.json.product_id, product_handle: i.json.product_handle,
  review_id: r.review_id, rating: r.rating, review_date: r.row.review_date, reviewer_name: r.row.reviewer_name,
  row: JSON.stringify(Object.fromEntries(Object.entries(r.row).filter(([k]) => !k.startsWith('_')))) } })));

const s = $('Collect settings').first().json;
const cut = (t, n) => t.length > n ? t.slice(0, n - 1) + '…' : t;
const quote = r => r ? '*' + '★'.repeat(r.rating) + '☆'.repeat(5 - r.rating) + '* ' + (r.title ? '*' + r.title + '*\n' : '') + cut(r.body, 900) + '\n_' + (r.author || 'Anonymous') + ', ' + r.date + '_' : '';
return $input.all().map(({ json: p }) => {
  const same = p.lowest && p.highest && p.lowest.rating === p.highest.rating;
  const blocks = [
    { type: 'header', text: { type: 'plain_text', text: cut('Reviews to check: ' + p.product_title, 150) } },
    { type: 'section', fields: [
      { type: 'mrkdwn', text: '*Your product*\n' + p.product_title + (p.model ? ' (' + p.model + ')' : '') },
      { type: 'mrkdwn', text: '*Manufacturer page*\n<' + p.url + '|' + cut(p.page_title || p.url, 120) + '>' },
      { type: 'mrkdwn', text: '*Reviews to import*\n' + p.review_count + ' of ' + p.stated_count + ', average ' + p.average },
      { type: 'mrkdwn', text: '*Stars*\n' + p.stars } ] },
    ...(p.left_out ? [{ type: 'context', elements: [{ type: 'mrkdwn', text: 'Left out: ' + p.left_out }] }] : []),
    // The lowest and highest rated reviews in full, so you can see the range before approving.
    { type: 'section', text: { type: 'mrkdwn', text: (same ? '*A review*' : '*Lowest rated*') + '\n' + quote(p.lowest) } },
    ...(p.review_count > 1 ? [{ type: 'section', text: { type: 'mrkdwn', text: (same ? '*Another review*' : '*Highest rated*') + '\n' + quote(p.highest) } }] : []),
    { type: 'context', elements: [{ type: 'mrkdwn', text: 'Approve only if this is the same product: same model, same pack size, same kit contents. Every review will show "First published on ' + p.source_name + '".' }] },
    { type: 'actions', block_id: 'review_actions', elements: [
      { type: 'button', action_id: 'reviews_approve', text: { type: 'plain_text', text: 'Approve' }, style: 'primary', value: String(p.id) },
      { type: 'button', action_id: 'reviews_reject', text: { type: 'plain_text', text: 'Reject' }, style: 'danger', value: String(p.id) } ] } ];
  return { json: { id: p.id, product_title: p.product_title, blocks, channel: s.slack_channel } };
});

// Reads the raw body first: Slack signs the exact bytes it sent. (A Set node before this would drop them.)
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const h = $input.first().json.headers;
const field = raw.split('&').find(kv => kv.startsWith('payload=')) || '';
let p = {};
try { p = JSON.parse(decodeURIComponent(field.slice(8).replace(/\+/g, ' '))); } catch (e) {}
const a = p.actions?.[0] || {};
return [{ json: {
  base: `v0:${h['x-slack-request-timestamp']}:${raw}`, expected: h['x-slack-signature'] || '',
  fresh: Math.abs(Date.now() / 1000 - Number(h['x-slack-request-timestamp'])) <= 300, retry: !!h['x-slack-retry-num'],
  app_id: p.api_app_id || '', user_id: p.user?.id || '', response_url: p.response_url || '',
  action: String(a.action_id || '').replace(/^reviews_/, ''), value: String(a.value || '') } }];

// New reviews of approved pages, whole products only, as a Judge.me import file.
const s = $('Export settings').first().json;
const pages = Object.fromEntries($('Get approved pages').all().map(i => i.json).filter(p => p.id).map(p => [p.id, p]));
const rows = $input.all().map(i => i.json).filter(r => r.key && pages[r.source_id]);
if (!rows.length) return [];
const byProduct = {};
for (const r of rows) (byProduct[r.product_handle] ||= []).push(r);
const take = [], products = [];
for (const [handle, list] of Object.entries(byProduct)) {
  if (take.length && take.length + list.length > s.max_rows) break;
  take.push(...list);
  products.push({ handle, title: pages[list[0].source_id].product_title, count: list.length, source: pages[list[0].source_id].source_name });
}
const cols = ['title', 'body', 'rating', 'review_date', 'reviewer_name', 'reviewer_email', 'product_handle', 'picture_urls', 'curated', 'reply',
  'CFFirst published on', 'CFSource page', 'CFReview continued'];
const q = v => '"' + String(v ?? '').replace(/"/g, '""') + '"';
const csv = cols.join(',') + '\r\n' + take.map(r => { const x = JSON.parse(r.row); return cols.map(c => q(x[c])).join(','); }).join('\r\n') + '\r\n';
const batch_id = 'batch-' + $now.toFormat('yyyyMMdd-HHmmss');
return [{ json: { batch_id, keys: take.map(r => r.key), count: take.length, products, channel: s.slack_channel, review_app: s.review_app },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(csv, 'utf8'), batch_id + '.csv', 'text/csv') } }];

const b = $json;
const lines = b.products.map(p => '• ' + p.title + ': ' + p.count + ' from ' + p.source).join('\n');
const blocks = [
  { type: 'header', text: { type: 'plain_text', text: b.count + ' reviews ready to import' } },
  { type: 'section', text: { type: 'mrkdwn', text: lines.slice(0, 2900) } },
  { type: 'section', text: { type: 'mrkdwn', text: 'The CSV is in the thread. In ' + b.review_app + ', go to *Reviews > Import > From review apps > Judge.me format*, attach it once, then check the import log for failed rows. Click *Mark imported* when it\'s done.' } },
  { type: 'actions', block_id: 'batch_actions', elements: [
    { type: 'button', action_id: 'reviews_imported', text: { type: 'plain_text', text: 'Mark imported' }, style: 'primary', value: b.batch_id } ] } ];
return [{ json: { ...b, blocks }, binary: $input.first().binary }];
